class Solution:
    def kthSmallest(self, matrix: list[list[int]], k: int) -> int:
        n = len(matrix)

        def count_le(x: int) -> int:
            # staircase walk from the bottom-left corner: O(n) steps
            r, c, cnt = n - 1, 0, 0
            while r >= 0 and c < n:
                if matrix[r][c] <= x:
                    cnt += r + 1        # whole column c from row 0 to r is <= x
                    c += 1
                else:
                    r -= 1
            return cnt

        lo, hi = matrix[0][0], matrix[-1][-1]
        while lo < hi:                  # O(log(max - min)) iterations
            mid = (lo + hi) // 2
            if count_le(mid) >= k:
                hi = mid                # mid could be the answer
            else:
                lo = mid + 1
        return lo                       # smallest value with at least k elements <= it

